V = [
(1, "Quel nombre complète la suite : 4, 6, 10, 16, 24, … ?", ["32","34","36","30"], "B", "Les écarts augmentent de 2 à chaque fois : +2, +4, +6, +8, puis +10. 24 + 10 = 34."),
(2, "Quel nombre complète la suite : 2, 8, 32, 128, … ?", ["256","384","512","640"], "C", "Chaque nombre est multiplié par 4 : 128 × 4 = 512."),
(3, "Quel nombre complète la suite : 7, 14, 28, 56, … ?", ["168","84","100","112"], "D", "Chaque nombre est le double du précédent : 56 × 2 = 112."),
(4, "Quel nombre complète la suite : 1, 3, 4, 7, 11, 18, … ?", ["29","25","36","27"], "A", "Chaque nombre est la somme des deux précédents : 11 + 18 = 29."),
(5, "Tous les élèves de la classe C ont un badge d'accès. Lina n'a pas de badge d'accès. Que peut-on en conclure ?", ["Lina est dans la classe C","On ne peut rien conclure","Tous les élèves sans badge sont dans la classe C","Lina n'est pas dans la classe C"], "D", "Si Lina était dans la classe C, elle aurait un badge. Comme elle n'en a pas, elle n'est pas dans la classe C."),
(6, "« Si le Wi-Fi est coupé, alors la console est hors ligne. » Le Wi-Fi n'est pas coupé. Que peut-on en conclure ?", ["La console est en ligne","La console est hors ligne","On ne peut pas savoir","Le Wi-Fi est coupé"], "C", "La règle dit seulement ce qui se passe quand le Wi-Fi est coupé. La console peut être hors ligne pour une autre raison (panne, mise à jour…)."),
(7, "Léa a terminé l'exercice avant Tom. Inès a terminé l'exercice après Léa. Qui a terminé en dernier ?", ["Léa a terminé en dernier","Tom a terminé en dernier","Inès a terminé en dernier","On ne peut pas savoir"], "D", "Tom et Inès ont tous les deux terminé après Léa, mais rien ne permet de les comparer entre eux."),
(8, "Un cadenas possède 3 molettes, chacune portant les chiffres de 0 à 9. Combien de combinaisons différentes existe-t-il ?", ["300","999","1 000","10 000"], "C", "10 possibilités par molette, 3 molettes : 10 × 10 × 10 = 1 000 (de 000 à 999)."),
(9, "Il est 23 h 35. Une mise à jour dure 1 h 50. À quelle heure se termine-t-elle ?", ["0 h 25","1 h 25","24 h 85","2 h 25"], "B", "23 h 35 + 1 h = 0 h 35 ; + 50 min = 1 h 25."),
(10, "Un programme teste 50 codes par seconde. Combien de temps lui faut-il, au maximum, pour tester tous les codes à 3 chiffres ?", ["20 secondes","2 secondes","200 secondes","50 secondes"], "A", "Il y a 1 000 codes (de 000 à 999) : 1 000 ÷ 50 = 20 secondes."),
(11, "Un fichier de 90 Go est téléchargé à la vitesse de 3 Go par minute. Combien de temps dure le téléchargement ?", ["45 minutes","3 heures","1 heure 30","30 minutes"], "D", "90 ÷ 3 = 30 minutes."),
(12, "Sur 300 comptes, 12 % ont un mot de passe trop faible. Combien de comptes sont concernés ?", ["36","24","12","48"], "A", "12 % de 300 = 0,12 × 300 = 36."),
(13, "Une imprimante imprime une affiche en 20 minutes. Combien d'affiches quatre imprimantes impriment-elles en 2 heures, au même rythme ?", ["8","24","12","6"], "B", "Une imprimante fait 6 affiches en 2 heures (120 ÷ 20) ; quatre imprimantes en font 4 × 6 = 24."),
(14, "Avec le chiffrement de César à décalage de 2, chaque lettre est remplacée par celle située 2 rangs plus loin (A devient C, B devient D…). Comment s'écrit le mot LOUP ?", ["MPVQ","NQWR","JMSN","NQXR"], "B", "L → N, O → Q, U → W, P → R. MPVQ correspond à un décalage de 1, JMSN à un décalage de 2 vers l'arrière."),
(15, "Un message a été chiffré avec le chiffrement de César à décalage de 2 (chaque lettre est remplacée par celle située 2 rangs plus loin). Quel mot se cache derrière le message chiffré TCV ?", ["VEX","SBU","RAT","RBT"], "C", "Pour déchiffrer, on recule de 2 rangs : T → R, C → A, V → T."),
(16, "Qu'affiche cet algorithme ?\na ← 7\nb ← a - 3\na ← b × 2\nAfficher a", ["14","4","8","11"], "C", "b vaut 7 - 3 = 4, puis a prend la valeur b × 2 = 8. L'ancienne valeur de a est remplacée."),
(17, "Qu'affiche cet algorithme ?\ntotal ← 0\nPour i allant de 2 à 5 :\n    total ← total + i\nAfficher total", ["14","5","9","15"], "A", "La boucle additionne 2 + 3 + 4 + 5 = 14."),
(18, "Qu'affiche cet algorithme ?\nstock ← 8\nSi stock < 10 alors\n    stock ← stock + 12\nAfficher stock", ["12","8","10","20"], "D", "8 est inférieur à 10 : la condition est vraie, on ajoute 12. stock vaut 20."),
(19, "Qu'affiche cet algorithme ?\nnote ← 12\nSi note < 10 alors\n    Afficher \"ajourné\"\nSinon\n    Afficher \"admis\"", ["ajourné","admis","Rien","ajourné puis admis"], "B", "12 n'est pas inférieur à 10 : c'est la branche Sinon qui s'exécute."),
(20, "Qu'affiche ce code Python ?\nmot = \"clavier\"\nprint(len(mot))", ["clavier","6","1","7"], "D", "len() renvoie le nombre de caractères de la chaîne : c, l, a, v, i, e, r, soit 7."),
(21, "Qu'affiche cet algorithme ?\nx ← 6\ny ← x - 2\nAfficher x + y", ["4","64","10","6"], "C", "y vaut 6 - 2 = 4, donc x + y = 6 + 4 = 10."),
(22, "Qu'affiche ce code Python ?\nmdp = \"tournesol\"\nif len(mdp) >= 8:\n    print(\"accepté\")\nelse:\n    print(\"trop court\")", ["accepté","trop court","Une erreur","trop court puis accepté"], "A", "« tournesol » contient 9 caractères, donc au moins 8 : c'est la branche if qui s'exécute."),
(23, "Qu'affiche ce code Python ?\nprenom = \"Yanis\"\nprint(prenom + \" est connecté\")", ["prenom est connecté","Yanis est connecté","Une erreur","est connecté Yanis"], "B", "La variable prenom contient « Yanis » ; le + colle les deux textes dans l'ordre où ils sont écrits."),
(24, "Dans un programme, à quoi sert une variable ?", ["À stocker une valeur pour la réutiliser","À répéter plusieurs fois des instructions","À connecter le programme à Internet","À afficher une image à l'écran"], "A", "Une variable est une case mémoire nommée qui garde une valeur (un nombre, un texte) que le programme peut lire ou modifier."),
(25, "Un compte se déverrouille si la personne a le bon mot de passe ET (un code SMS correct OU sa clé de sécurité). Sami a le bon mot de passe, un code SMS faux, et il a sa clé de sécurité. Que se passe-t-il ?", ["Le compte reste verrouillé","On ne peut pas savoir","Il faut d'abord un nouveau code SMS","Le compte se déverrouille"], "D", "La parenthèse est vraie grâce à la clé (un seul côté du OU suffit) et le mot de passe est bon : les deux côtés du ET sont vrais."),
(26, "Que vaut le nombre binaire 1101 en décimal ?", ["11","13","1101","14"], "B", "1101 = 1×8 + 1×4 + 0×2 + 1×1 = 13."),
(27, "En binaire, combien de valeurs différentes un seul bit peut-il prendre ?", ["1","10","8","2"], "D", "Un bit vaut soit 0, soit 1 : il a donc 2 valeurs possibles, comme un courant qui passe ou ne passe pas."),
(28, "Combien d'octets représentent 32 bits ?", ["4","8","32","256"], "A", "Un octet contient 8 bits : 32 ÷ 8 = 4 octets."),
(29, "Un fichier pèse 3 Mo. Combien cela représente-t-il de Ko (kilooctets) ?", ["300 Ko","30 Ko","3 000 Ko","3 000 000 Ko"], "C", "1 Mo = 1 000 Ko, donc 3 Mo = 3 000 Ko (on compterait 1 024 avec les unités Mio et Kio)."),
(30, "Lequel de ces composants conserve vos fichiers lorsque l'ordinateur est éteint ?", ["La mémoire vive (RAM)","Le disque SSD","L'écran","La carte réseau"], "B", "Le SSD est un stockage permanent. La RAM s'efface hors tension, et l'écran comme la carte réseau ne stockent pas vos fichiers."),
(31, "Cochez les éléments qui sont des logiciels (software) (plusieurs réponses possibles) :", ["Un navigateur web","Le système d'exploitation","Un traitement de texte","Le disque dur"], "A,B,C", "Le disque dur est un composant physique (hardware). Les trois autres sont des programmes."),
(32, "Qu'est-ce qu'une adresse IP, comme 192.168.1.20 ?", ["Un code secret qui protège l'accès au réseau Wi-Fi","Un numéro qui identifie un appareil sur un réseau","Le numéro de série gravé dans le processeur","Une mesure de la vitesse de la connexion"], "B", "Comme une adresse postale, l'adresse IP permet d'acheminer les données vers le bon appareil du réseau."),
(33, "Dans une maison, quel appareil distribue le Wi-Fi et relie le téléphone, l'ordinateur et la console à Internet ?", ["L'antivirus de l'ordinateur","Le disque dur externe","La box Internet","Le système d'exploitation"], "C", "La box fait le lien entre le réseau de la maison et celui de l'opérateur. L'antivirus et le système d'exploitation sont des logiciels."),
(34, "L'adresse d'un site commence par « https:// ». Que cela garantit-il ?", ["Les échanges sont chiffrés, mais le site peut être frauduleux","Le site appartient à une entreprise connue et fiable","Le site a été vérifié par un antivirus officiel","Le site ne peut pas collecter de données personnelles"], "A", "Le « s » de https indique une connexion chiffrée. Les sites d'hameçonnage l'utilisent aussi : ce n'est pas une preuve d'honnêteté."),
(35, "Qu'est-ce qu'un logiciel « propriétaire » (le contraire d'un logiciel open source) ?", ["Un logiciel dont le code source n'est pas rendu public","Un logiciel installé uniquement sur votre propre ordinateur","Un logiciel que vous avez programmé vous-même","Un logiciel forcément payant et sans aucune faille"], "A", "Un logiciel propriétaire garde son code source secret. Il peut être gratuit ou payant, et contenir des failles comme tout logiciel."),
(36, "Vous recevez un mail : « Votre abonnement de streaming va être suspendu, mettez à jour votre carte bancaire ici » avec un lien vers abonnement-securite-paiement.net. Que faites-vous ?", ["Cliquer et mettre à jour la carte pour ne pas perdre l'accès","Répondre au mail pour demander s'il s'agit d'une arnaque","Transférer le mail à vos amis pour qu'ils vérifient aussi","Ne pas cliquer et vérifier depuis l'application ou le site officiel"], "D", "C'est un hameçonnage classique : le lien mène vers un faux site qui vole les données bancaires. On vérifie toujours par le canal officiel."),
(37, "Cochez les indices qui doivent faire penser à une arnaque dans un SMS (plusieurs réponses possibles) :", ["Le message ne contient aucune faute d'orthographe","Un lien vers un site au nom inhabituel","Une demande de transmettre un code reçu par SMS","Un gain inattendu à réclamer avant ce soir"], "B,C,D", "Un message bien écrit ne prouve rien : les arnaques soignées existent. Le lien suspect, la demande de code et le gain urgent sont des signaux d'alerte."),
(38, "Parmi ces mots de passe, lequel résiste le mieux à une tentative de piratage ?", ["Football2010!","Motdepasse123","R7#mq2!Lz9vW-p4T","Ch@t-N0ir-2009"], "C", "Il est long et aléatoire, sans mot du dictionnaire ni date. Les autres reprennent des mots et des années, testés en premier par les attaquants."),
(39, "Un site sur lequel vous avez un compte annonce une fuite de mots de passe. Vous utilisez ce même mot de passe pour votre messagerie. Que faites-vous en priorité ?", ["Rien : la fuite concerne ce site, pas votre messagerie","Changer ce mot de passe partout où vous l'utilisez","Supprimer seulement votre compte sur le site touché","Attendre un mail suspect avant de changer quoi que ce soit"], "B", "Les attaquants testent les mots de passe volés sur d'autres services : il faut le changer partout, avec un mot de passe différent par compte."),
(40, "Un pirate a obtenu votre mot de passe, mais votre compte est protégé par la double authentification. Que se passe-t-il quand il essaie de se connecter ?", ["Il entre : la double authentification ne protège que les achats","Le site change votre mot de passe automatiquement","Le site supprime votre compte pour le protéger","Il est bloqué, car il lui manque le code de votre téléphone"], "D", "La double authentification exige un second élément (code, application) que le pirate n'a pas, même s'il connaît le mot de passe."),
(41, "À l'aéroport, un Wi-Fi gratuit sans mot de passe vous demande, pour vous connecter, l'identifiant et le mot de passe de votre messagerie. Que faites-vous ?", ["Refuser : un Wi-Fi public n'a pas besoin du mot de passe de votre messagerie","Les saisir : un Wi-Fi d'aéroport est forcément géré par l'aéroport","Les saisir, puis changer le mot de passe une fois rentré chez vous","Les saisir seulement si la connexion semble rapide et stable"], "A", "C'est probablement un faux point d'accès qui collecte des identifiants. Aucun Wi-Fi légitime ne demande le mot de passe d'un autre service."),
(42, "Pendant votre stage, vous recevez par courrier une clé USB « cadeau » envoyée par une entreprise que personne ne connaît. Que faites-vous ?", ["La brancher pour découvrir ce qu'elle contient","La brancher sur l'ordinateur d'un collègue plutôt que le vôtre","Ne pas la brancher et la remettre au service informatique","La formater d'abord, puis l'utiliser normalement"], "C", "Une clé piégée peut infecter l'ordinateur dès qu'elle est branchée, même sans ouvrir de fichier. L'envoi de clés « cadeaux » est une technique d'attaque connue."),
(43, "Une application n'est plus mise à jour par son éditeur depuis plusieurs années. Quel est le principal risque à continuer de l'utiliser ?", ["Ses failles connues ne seront plus corrigées et pourront être exploitées","Elle va s'effacer d'elle-même au bout de quelques mois","Elle devient interdite par la loi dès la fin des mises à jour","Elle consomme automatiquement davantage de forfait mobile"], "A", "Sans mises à jour, les failles découvertes restent ouvertes et les attaquants peuvent les exploiter."),
(44, "Un programme rend tous les fichiers d'un ordinateur illisibles et affiche : « Payez pour récupérer vos données ». De quel type d'attaque s'agit-il ?", ["Un hameçonnage (phishing)","Un logiciel publicitaire (adware)","Un rançongiciel (ransomware)","Une attaque par force brute"], "C", "Le rançongiciel chiffre les fichiers puis réclame une rançon. Des sauvegardes régulières et déconnectées permettent de récupérer les données sans payer."),
(45, "Laquelle de ces informations n'est PAS une donnée personnelle ?", ["Votre numéro de téléphone","La photo de votre visage","L'adresse de votre domicile","Le prix d'un ticket de bus"], "D", "Une donnée personnelle permet d'identifier une personne. Le prix d'un ticket de bus ne concerne personne en particulier."),
(46, "Un site affiche : « Your username can contain up to 20 characters. » Que signifie ce message ?", ["Le nom d'utilisateur doit contenir au moins 20 caractères","Le nom d'utilisateur peut contenir jusqu'à 20 caractères","Le nom d'utilisateur doit contenir exactement 20 caractères","Le nom d'utilisateur doit contenir 20 chiffres"], "B", "« Up to » signifie « jusqu'à » : 20 caractères au maximum. « At least » signifierait « au moins »."),
(47, "Un message affiche : « Login failed. Please try again later. » Que signifie-t-il ?", ["La connexion a réussi ; vous pouvez continuer","Le compte a été supprimé définitivement","Il faut changer de mot de passe tout de suite","La connexion a échoué ; réessayez plus tard"], "D", "« Login failed » = la connexion a échoué ; « try again later » = réessayez plus tard."),
(48, "Un mail indique : « We will never ask for your password by phone or email. » Que faut-il comprendre ?", ["L'entreprise ne demandera jamais votre mot de passe, ni par téléphone ni par mail","L'entreprise vous demandera votre mot de passe par téléphone","Il vaut mieux envoyer le mot de passe par mail que par téléphone","L'entreprise va bientôt vous appeler pour vérifier le mot de passe"], "A", "« We will never ask » = nous ne demanderons jamais. Quelqu'un qui réclame votre mot de passe au nom de l'entreprise est un fraudeur."),
(49, "Un message affiche : « Your account will be locked after three failed attempts. » Que signifie-t-il ?", ["Le compte est déjà bloqué après trois tentatives","Le compte sera bloqué après trois tentatives échouées","Il reste trois jours avant le blocage du compte","Le compte sera débloqué après trois tentatives"], "B", "« Will be locked » = sera bloqué ; « after three failed attempts » = après trois tentatives échouées."),
(50, "Le navigateur affiche : « This website may be unsafe. Do you want to continue? » Que signifie ce message ?", ["Ce site pourrait être dangereux ; voulez-vous quand même continuer ?","Ce site est en maintenance ; voulez-vous revenir plus tard ?","Ce site est trop lent ; voulez-vous changer de réseau ?","Ce site a été mis à jour ; voulez-vous le recharger ?"], "A", "« May be unsafe » = pourrait être dangereux ; « continue » = continuer. Dans le doute, on ne poursuit pas."),
(51, "Énigme CYBEROKU. Dans cette grille, chaque ligne et chaque colonne contient une seule fois les chiffres 1, 2, 3 et 4.\n2 . 4 3\n4 . ? 1\n. 4 3 .\n3 2 . 4\nQuel chiffre remplace le « ? » ?", ["1","2","3","4"], "B", "Sur sa ligne, il manque 2 et 3. Dans sa colonne, il y a déjà 4 et 3. Il ne reste que 2."),
(52, "Énigme CYBEROKU. Dans cette grille, chaque ligne et chaque colonne contient une seule fois les symboles *, = et +.\n* = +\n? * =\n= + *\nQuel symbole remplace le « ? » ?", ["=","*","+","On ne peut pas savoir"], "C", "La ligne contient déjà * et =, la colonne contient déjà * et = : il ne reste que +."),
(53, "Énigme CYBEROKU. Un message est codé : chaque lettre est remplacée par son rang dans l'alphabet (A = 1, B = 2…). Que signifie 3 15 4 5 ?", ["BODE","CPDE","CODF","CODE"], "D", "3 = C, 15 = O, 4 = D, 5 = E."),
(54, "Énigme CYBEROKU. Un mot de passe est caché dans ce journal : prenez la première lettre de chaque ligne.\nConnexion réussie\nLecture du disque\nErreur corrigée\nFermeture du port\nQuel est le mot caché ?", ["CLEF","CLES","FLEC","CREF"], "A", "Les premières lettres des lignes donnent C, L, E, F."),
(55, "Énigme CYBEROKU. Hugo, Inès et Malik ont chacun résolu un défi différent : web, forensic ou stégano. Malik n'a pas résolu le défi forensic. Hugo a résolu le défi web. Qui a résolu le défi forensic ?", ["Hugo","Malik","Inès","On ne peut pas savoir"], "C", "Hugo a web. Malik n'a pas forensic, donc il a stégano, et Inès a forensic."),
]
